"""Camera restoration comparison page; originals are never overwritten."""
HTML = r'''<!doctype html><html lang="en"><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>PalmIR Palmprint restoration</title><style>
*{box-sizing:border-box}body{margin:0;background:#f3f5f7;color:#17212b;font:16px system-ui,sans-serif}
header,main{max-width:1080px;margin:auto;padding:20px}header{display:flex;justify-content:space-between;align-items:center;gap:16px}
h1{font-size:24px}h2{font-size:18px}a{color:#125e9c}.card{background:white;border:1px solid #dce2e8;border-radius:12px;padding:20px;margin-bottom:16px}
#view{position:relative;background:#141b22;line-height:0;max-width:720px;margin:auto}#camera{width:100%;height:auto}#box{position:absolute;border:2px solid #6effb1;pointer-events:none}
.controls{display:flex;flex-wrap:wrap;gap:20px;margin:18px 0}label{display:flex;align-items:center;gap:8px}input{max-width:150px}
button{background:#12624c;color:white;border:0;border-radius:8px;padding:12px 18px;font:inherit;cursor:pointer}button:disabled{opacity:.5}
.pair{display:grid;grid-template-columns:1fr 1fr;gap:20px}.pair img{width:100%;max-width:320px;image-rendering:auto;border-radius:8px;background:#ddd}
.muted{color:#546576;line-height:1.6}#status{white-space:pre-wrap}figure{margin:0}figcaption{margin-bottom:10px}#results[hidden]{display:none}
</style><header><h1>PalmIR Palmprint restoration</h1><span><a href="/palmir-report">Historical image tests and examples</a> · <a href="/collect">Back to original capture</a></span></header><main>
<section class="card"><h2>Select palm region</h2><p>Place your palm in the green box. Click the image or use the sliders to move the box. Capture and freeze the original before selecting the region.</p>
<p id="focusStatus" class="muted">Checking autofocus…</p><button id="focus" disabled>Enable continuous autofocus</button><p class="muted">Keep your palm still and wait for a clear image before capture. Enabling autofocus does not guarantee every photo is in focus.</p>
<div id="view"><img id="camera" alt="Live camera feed"><div id="box"></div></div>
<div class="controls"><label>Horizontal<input id="x" type="range" min="0" max="100" value="50"></label><label>Vertical<input id="y" type="range" min="0" max="100" value="50"></label><label>Size<input id="size" type="range" min="10" max="100" value="50"></label></div>
<button id="snapshot">Capture original / Retake</button> <button id="reference" disabled>Set as reference palmprint</button> <button id="run" disabled>Restore selected palm region</button><p id="status" role="status">Capture an original before selecting a palm region</p>
<p id="compareStatus" class="muted">Set a reference palmprint, then recapture the same hand to compare DoN matching distances before and after restoration. Lower means more similar. No acceptance threshold is calibrated; this is not a pass rate.</p>
<p id="qualityStatus" class="muted">Low contrast or shadow is not the same as blur. Improve lighting, focus and palm localization first. The model may reduce recognition success under some blur conditions.</p>
<p class="muted">Uses a locally trained PalmIR-style RIA model. The input is a manually selected 128 × 128 palm region. It neither localizes palmprints automatically nor identifies people. Restoration performance on this camera has not been verified.</p></section>
<section class="card" id="results" hidden><h2>Restoration comparison for this capture</h2><div class="pair"><figure><figcaption>Before restoration · 128 × 128</figcaption><img id="original" alt="Palm region before restoration"><p><a id="downloadOriginal" download="palm-original.png">Download input image</a></p></figure><figure><figcaption>After model restoration · 128 × 128</figcaption><img id="restored" alt="Restored palm region"><p><a id="downloadRestored" download="palm-restored.png">Download restored image</a></p></figure></div><p><a id="downloadSource" download="palm-source.png">Download full original</a></p><p class="muted">Images are kept only on this page; download them to save. The model may change palmprint details. Original capture data is not overwritten.</p></section></main>
<script>
const camera=document.getElementById('camera'),box=document.getElementById('box'),view=document.getElementById('view');
const focusStatus=document.getElementById('focusStatus'),focusButton=document.getElementById('focus');
async function checkFocus(method='GET'){try{const r=await fetch('/api/camera/focus',{method,headers:method==='POST'?{'Content-Type':'application/json'}:{},body:method==='POST'?'{}':undefined});const d=await r.json();focusStatus.textContent=d.supported?(d.continuous?'Continuous autofocus enabled':'Camera supports autofocus; currently disabled'):'Camera provides no usable autofocus control';focusButton.disabled=!d.supported;}catch(e){focusStatus.textContent='Autofocus status unavailable'}}focusButton.onclick=()=>checkFocus('POST');checkFocus();
const x=document.getElementById('x'),y=document.getElementById('y'),size=document.getElementById('size'),run=document.getElementById('run'),status=document.getElementById('status'),snapshot=document.getElementById('snapshot');const reference=document.getElementById('reference'),compareStatus=document.getElementById('compareStatus');let busy=false,snapshotId=null;
function draw(){let w=camera.clientWidth,h=camera.clientHeight,s=Math.min(w,h)*size.value/100;box.style.width=s+'px';box.style.height=s+'px';box.style.left=Math.min(w-s,Math.max(0,w*x.value/100-s/2))+'px';box.style.top=Math.min(h-s,Math.max(0,h*y.value/100-s/2))+'px'}
[x,y,size].forEach(el=>el.oninput=draw);window.addEventListener('resize',draw);camera.onload=()=>{draw();setTimeout(poll,250)};camera.onerror=()=>setTimeout(poll,1000);
function poll(){if(snapshotId)return;if(!busy)camera.src='/frame.jpg?t='+Date.now();else setTimeout(poll,250)}poll();
view.onclick=e=>{const r=camera.getBoundingClientRect();x.value=Math.round(100*(e.clientX-r.left)/r.width);y.value=Math.round(100*(e.clientY-r.top)/r.height);draw()};
snapshot.onclick=async()=>{busy=true;snapshot.disabled=true;run.disabled=true;status.textContent='Capturing original…';try{const r=await fetch('/api/palmir/snapshot',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});const d=await r.json();if(!r.ok)throw Error(d.message||'Capture failed');snapshotId=d.snapshot_id;camera.src=d.source;document.getElementById('results').hidden=true;status.textContent='Original frozen. Click the palm, adjust the green box, then click Restore.'}catch(e){status.textContent='Incomplete: '+e.message}finally{busy=false;snapshot.disabled=false;run.disabled=!snapshotId;reference.disabled=!snapshotId}};
reference.onclick=async()=>{reference.disabled=true;try{const r=await fetch('/api/palmir/reference',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({snapshot_id:snapshotId,x:x.value/100,y:y.value/100,size:size.value/100})});const d=await r.json();if(!r.ok)throw Error(d.message||'Setup failed');compareStatus.textContent='Reference palmprint set. Capture again and select the same palm region for a restoration comparison.'}catch(e){compareStatus.textContent=e.message}finally{reference.disabled=false}};
run.onclick=async()=>{busy=true;run.disabled=true;snapshot.disabled=true;reference.disabled=true;status.textContent='Restoring…';try{const r=await fetch('/api/palmir/restore',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({snapshot_id:snapshotId,x:x.value/100,y:y.value/100,size:size.value/100})});const d=await r.json();if(!r.ok)throw Error(d.message||'Restoration failed');for(const id of ['original','restored']){document.getElementById(id).src=d[id];document.getElementById('download'+id[0].toUpperCase()+id.slice(1)).href=d[id]}if(d.don_comparison){const c=d.don_comparison;compareStatus.textContent=d.same_as_reference?'This is the reference image itself. Capture again before comparing.':`DoN Matching distance (lower is better): before ${c.raw_distance.toFixed(5)} / after ${c.restored_distance.toFixed(5)} / improvement ${c.improvement>=0?'+':''}${c.improvement.toFixed(5)}. This compares scores, not pass rates.`}if(d.input_quality){const q=d.input_quality;document.getElementById('qualityStatus').textContent=`Input contrast ${q.contrast.toFixed(1)}.`+(q.low_contrast_warning?' below advisory threshold 12. Add light or adjust pose and retake. Test samples are not automatically excluded.':'This value does not guarantee correct palm localization.')}document.getElementById('downloadSource').href=d.source;document.getElementById('results').hidden=false;status.textContent=`Restoration complete · Model inference ${d.inference_ms} ms · Input ${d.input_size} × ${d.input_size} · Original ${d.source_size.join(' × ')}`;}catch(e){status.textContent='Incomplete: '+e.message}finally{busy=false;run.disabled=false;snapshot.disabled=false;reference.disabled=false}};
</script></html>'''
